else if (SetupReq.bRequest == USB_REQ_GET_DESCRIPTOR)
{
    switch ((u8)(SetupReq.wValue >> 8))       /* 高字节是描述符类型 */
    {
        case USB_DESC_DEVICE:
            USB_HW_EpTx(0, device_desc,
                        (SetupReq.wLength < 18) ? SetupReq.wLength : 18);
            break;
        case USB_DESC_CONFIGURATION:
            USB_HW_EpTx(0, config_desc,
                        (SetupReq.wLength < 34) ? SetupReq.wLength : 34);
            break;
        case USB_DESC_REPORT:
            USB_HW_EpTx(0, report_desc,
                        (SetupReq.wLength < 62) ? SetupReq.wLength : 62);
            break;
        default:
            break;
    }
}

if (SetupReq.bRequest == USB_REQ_SET_ADDRESS)
{
    usb_pending_addr = (u8)(SetupReq.wValue & 0x7F);   /* 先暂存 */
}
/* CTR_TX 中断里：状态阶段 IN 空包发完，地址才生效 */
if (usb_pending_addr)
{
    USB->DADDR = (usb_pending_addr | (1U << 7));
    usb_pending_addr = 0;
}

else if (SetupReq.bRequest == USB_REQ_SET_CONFIGURATION)
{
    usb_config_value = (u8)(SetupReq.wValue & 0xFF);
    if (usb_config_value == 1)
    {
        USB_Ep1_Init();          /* 配置完成，EP1 开始工作 */
    }
}
/* 然后 wLength==0 统一回空包（状态阶段 IN ZLP） */

void USB_Ep1_Init(void)
{
    USB_PMA[1].ADDR_TX  = usb_ep_tx_addr[1];   /* 0xA0 */
    USB_PMA[1].COUNT_TX = 4;

    /* STAT_TX 先 DISABLED，USB_HW_EpTx 内部翻转开门 */
    USB->EP1R = (((u16)EP_STAT_NAK << 12) | (3U << 9));
    USB_HW_EpTx(1, test_desc, 4);              /* 先发一帧全 0 报告 */
}

/* 修复前：0x2630，EA=0，主机轮询 EP1 无响应 */
USB->EP1R = (((u16)EP_STAT_NAK << 12) | ((u16)EP_STAT_VALID << 4) | (3U << 9));

/* 修复后：0x2631，EA=1，主机 IN 令牌命中 */
USB->EP1R = (((u16)EP_STAT_NAK << 12) | ((u16)EP_STAT_VALID << 4) | (3U << 9) | 1U);

PWM3360_ReadMotion(&motion);
Mouse_BuildReport(&motion, mouse_report);
if (usb_config_value == 1)          /* 只有 SET_CONFIGURATION 之后才发 */
{
    USB_HW_EpTx(1, mouse_report, 6);
}
